<?php
session_name('lootzone_admin');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>true,'httponly'=>true,'samesite'=>'Lax']);session_start();
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');require_once __DIR__.'/db.php';require_once (is_file(__DIR__.'/backend/api/common.php') ? __DIR__.'/backend/api/common.php' : __DIR__.'/../backend/api/common.php');
function out($d,$c=200){http_response_code($c);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function csrf_ok(){return isset($_SESSION['csrf'])&&hash_equals($_SESSION['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??'');}
$method=$_SERVER['REQUEST_METHOD'];
if($method==='GET'&&($_GET['action']??'')==='bootstrap'){
 if(empty($_SESSION['admin']))out(['authenticated'=>false]);try{$pdo=lootzone_db();$stats=$pdo->query("SELECT COUNT(*) total,COUNT(*) FILTER(WHERE status='processing') processing,COUNT(*) FILTER(WHERE status='accepted') accepted,COUNT(*) FILTER(WHERE status='in_progress') in_progress,COUNT(*) FILTER(WHERE status='completed') completed,COUNT(*) FILTER(WHERE status='cancelled') cancelled FROM orders")->fetch();
 $active=$pdo->query("SELECT * FROM orders WHERE status<>'cancelled' ORDER BY created_at DESC LIMIT 500")->fetchAll();$archive=$pdo->query("SELECT * FROM orders WHERE status='cancelled' ORDER BY updated_at DESC LIMIT 500")->fetchAll();out(['authenticated'=>true,'csrf'=>$_SESSION['csrf'],'stats'=>$stats,'orders'=>$active,'cancelled_orders'=>$archive]);
 }catch(Throwable $e){error_log('Admin bootstrap: '.$e->getMessage());out(['error'=>'database_unavailable'],503);}}
if($method!=='POST')out(['error'=>'method'],405);$body=json_decode(file_get_contents('php://input'),true)?:[];$action=$body['action']??'';
if($action==='login'){$eu=getenv('ADMIN_USERNAME')?:'admin';$ep=getenv('ADMIN_PASSWORD')?:'';if($ep==='')out(['error'=>'admin_not_configured'],503);if(!empty($_SESSION['lock_until'])&&time()<$_SESSION['lock_until'])out(['error'=>'too_many_attempts'],429);$u=(string)($body['username']??'');$p=(string)($body['password']??'');if(!hash_equals($eu,$u)||!hash_equals($ep,$p)){$_SESSION['fails']=($_SESSION['fails']??0)+1;if($_SESSION['fails']>=6){$_SESSION['lock_until']=time()+300;$_SESSION['fails']=0;}out(['error'=>'invalid_credentials'],401);}session_regenerate_id(true);$_SESSION['admin']=true;$_SESSION['fails']=0;$_SESSION['csrf']=bin2hex(random_bytes(32));out(['ok'=>true,'csrf'=>$_SESSION['csrf']]);}
if(empty($_SESSION['admin']))out(['error'=>'unauthorized'],401);if(!csrf_ok())out(['error'=>'csrf'],403);
if($action==='logout'){$_SESSION=[];session_destroy();out(['ok'=>true]);}
if($action==='update_status'){$code=trim((string)($body['order_code']??''));$status=(string)($body['status']??'');$allowed=['processing','accepted','in_progress','completed','cancelled'];if($code===''||!in_array($status,$allowed,true))out(['error'=>'invalid_input'],422);
 try{$pdo=lootzone_db();$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,user_uid,status FROM orders WHERE order_code=:c FOR UPDATE');$q->execute([':c'=>$code]);$o=$q->fetch();if(!$o){$pdo->rollBack();out(['error'=>'not_found'],404);}if($o['status']===$status){$pdo->commit();out(['ok'=>true,'unchanged'=>true]);}
 $u=$pdo->prepare('UPDATE orders SET status=:s,updated_at=NOW() WHERE id=:id');$u->execute([':s'=>$status,':id'=>$o['id']]);$h=$pdo->prepare('INSERT INTO order_status_history(order_id,old_status,new_status,changed_by) VALUES(:id,:old,:new,\'admin\')');$h->execute([':id'=>$o['id'],':old'=>$o['status'],':new'=>$status]);$pdo->commit();try{lz_notify_order($pdo,(int)$o['id'],$o['user_uid']??null,$code,$status);}catch(Throwable $pushError){error_log('Admin notification error: '.$pushError->getMessage());}out(['ok'=>true]);
 }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Admin update status: '.$e->getMessage());out(['error'=>'database_error'],503);}}
out(['error'=>'unknown_action'],400);
